changeSet.sql:
DO $$
BEGIN
    IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'liquibase_ddl') THEN
        CREATE ROLE liquibase_ddl;
    END IF;
    IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'worker_dml') THEN
        CREATE ROLE worker_dml;
    END IF;
    IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'powerbi_reader') THEN
        CREATE ROLE powerbi_reader;
    END IF;
END
$$;

-- Revoke public create privileges across all pipeline schemas
REVOKE CREATE ON SCHEMA staging, analytics, batch FROM PUBLIC;

-- liquibase_ddl: migration administrator with DDL across all pipeline schemas
GRANT USAGE, CREATE ON SCHEMA staging, analytics, batch TO liquibase_ddl;
GRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA staging, analytics, batch TO liquibase_ddl;
GRANT ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA staging, analytics, batch TO liquibase_ddl;

-- worker_dml: operational data manipulation across staging, analytics, and batch
GRANT USAGE ON SCHEMA staging, analytics, batch TO worker_dml;
GRANT SELECT, INSERT, UPDATE ON ALL TABLES IN SCHEMA staging TO worker_dml;
REVOKE DELETE, TRUNCATE ON ALL TABLES IN SCHEMA staging FROM worker_dml;
REVOKE CREATE ON SCHEMA staging, analytics, batch FROM worker_dml;

GRANT SELECT, INSERT, UPDATE ON ALL TABLES IN SCHEMA analytics TO worker_dml;
GRANT USAGE, SELECT, UPDATE ON ALL SEQUENCES IN SCHEMA analytics TO worker_dml;

GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA batch TO worker_dml;
GRANT USAGE, SELECT, UPDATE ON ALL SEQUENCES IN SCHEMA batch TO worker_dml;

-- powerbi_reader: read-only access strictly to analytical star-schema tables
REVOKE ALL ON SCHEMA staging, batch FROM powerbi_reader;
GRANT USAGE ON SCHEMA analytics TO powerbi_reader;
GRANT SELECT ON TABLE analytics.dim_date,
                      analytics.dim_time,
                      analytics.dim_region,
                      analytics.dim_item,
                      analytics.dim_station,
                      analytics.fact_market_daily_summary,
                      analytics.fact_order_book_liquidity TO powerbi_reader;

-- Explicitly deny powerbi_reader access to internal operational sync metadata and sequences
REVOKE ALL ON TABLE analytics.sde_metadata FROM powerbi_reader;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA analytics FROM powerbi_reader;

-- Default privileges for future tables/sequences
ALTER DEFAULT PRIVILEGES IN SCHEMA staging GRANT SELECT, INSERT, UPDATE ON TABLES TO worker_dml;
ALTER DEFAULT PRIVILEGES IN SCHEMA analytics GRANT SELECT, INSERT, UPDATE ON TABLES TO worker_dml;
ALTER DEFAULT PRIVILEGES IN SCHEMA analytics GRANT USAGE, SELECT, UPDATE ON SEQUENCES TO worker_dml;
ALTER DEFAULT PRIVILEGES IN SCHEMA batch GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO worker_dml;
ALTER DEFAULT PRIVILEGES IN SCHEMA batch GRANT USAGE, SELECT, UPDATE ON SEQUENCES TO worker_dml;
ALTER DEFAULT PRIVILEGES IN SCHEMA analytics GRANT SELECT ON TABLES TO powerbi_reader;

DO $$
BEGIN
    IF pg_has_role(CURRENT_USER, 'liquibase_ddl', 'MEMBER') OR CURRENT_USER = 'liquibase_ddl' THEN
        ALTER DEFAULT PRIVILEGES FOR ROLE liquibase_ddl IN SCHEMA staging GRANT SELECT, INSERT, UPDATE ON TABLES TO worker_dml;
        ALTER DEFAULT PRIVILEGES FOR ROLE liquibase_ddl IN SCHEMA analytics GRANT SELECT, INSERT, UPDATE ON TABLES TO worker_dml;
        ALTER DEFAULT PRIVILEGES FOR ROLE liquibase_ddl IN SCHEMA analytics GRANT USAGE, SELECT, UPDATE ON SEQUENCES TO worker_dml;
        ALTER DEFAULT PRIVILEGES FOR ROLE liquibase_ddl IN SCHEMA batch GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO worker_dml;
        ALTER DEFAULT PRIVILEGES FOR ROLE liquibase_ddl IN SCHEMA batch GRANT USAGE, SELECT, UPDATE ON SEQUENCES TO worker_dml;
        ALTER DEFAULT PRIVILEGES FOR ROLE liquibase_ddl IN SCHEMA analytics GRANT SELECT ON TABLES TO powerbi_reader;
    END IF;
EXCEPTION WHEN OTHERS THEN
    NULL;
END
$$;
